const body = $json.body ?? {};
const code = String(body.code ?? '').trim();
const providedLanguage = String(body.language ?? '').trim().toLowerCase();
const context = String(body.context ?? 'Não informado').trim();
const model = String(body.model ?? 'openai/gpt-4o-mini').trim();
const startedAt = Date.now();
function inferLanguage(input, source) {
  if (input) return input;
  if (/def\s+\w+\(|import\s+.+from\s+|self\.|pytest/.test(source)) return 'python';
  if (/<\?php|function\s+\w+\(|->|namespace\s+/.test(source)) return 'php';
  if (/interface\s+\w+|type\s+\w+\s*=|:\s*(string|number|boolean)|implements\s+/.test(source)) return 'typescript';
  if (/function\s+\w+\(|const\s+|let\s+|=>|module\.exports/.test(source)) return 'javascript';
  return 'generic';
}
const language = inferLanguage(providedLanguage, code);
const agents = {
  typescript: { name: 'typescript-review-agent', focus: 'TypeScript avançado, tipagem forte, async/await, arquitetura modular, segurança, testes Jest/Vitest e qualidade de API.' },
  javascript: { name: 'javascript-review-agent', focus: 'JavaScript moderno, Node.js/browser, promises, closures, validação, segurança, performance e testes.' },
  python: { name: 'python-review-agent', focus: 'Python, typing, PEP8, erros comuns, segurança, performance, pytest e organização de módulos.' },
  php: { name: 'php-review-agent', focus: 'PHP moderno, PSR, Composer, segurança web, validação, performance e testes PHPUnit.' },
  generic: { name: 'generic-review-agent', focus: 'Revisão geral de código, bugs, segurança, qualidade, performance, testes e manutenibilidade.' }
};
const agent = agents[language] ?? agents.generic;
const validationErrors = [];
if (!code) validationErrors.push({ field: 'code', message: 'O campo code é obrigatório.' });
if (code.length > 60000) validationErrors.push({ field: 'code', message: 'O código enviado é grande demais para este endpoint.' });
const runId = `run_${Date.now()}_${Math.random().toString(16).slice(2)}`;
const schema = { score: 0, severity: 'low|medium|high|critical', summary: 'string', assessment: 'approve|needs_work|requires_changes', positive_observations: ['string'], findings: [{ severity: 'critical|warning|suggestion', category: 'functionality|security|quality|testing|performance|maintainability', message: 'string', recommendation: 'string' }], recommendations: ['string'], test_suggestions: ['string'], security_notes: ['string'], complexity_assessment: 'string' };
const systemPrompt = `Você é o ${agent.name}. Foco: ${agent.focus} Você deve atuar como AI Agent especialista de code review. Responda APENAS JSON válido, sem markdown fora do JSON, no schema: ${JSON.stringify(schema)}. Seja criterioso, profissional e objetivo em pt-BR. Use severidades: critical para falhas graves, warning para problemas relevantes, suggestion para melhorias. Atribua score de 0 a 100.`;
const userPrompt = validationErrors.length > 0 ? `Entrada inválida. Retorne JSON com assessment requires_changes e findings de validação: ${JSON.stringify(validationErrors)}` : `Contexto do projeto/case: ${context}\nLinguagem detectada: ${language}\n\nCódigo para revisão:\n\`\`\`\n${code}\n\`\`\``;
return [{ json: { run_id: runId, started_at_ms: startedAt, code, language, context, model, specialist_agent: agent.name, system_prompt: systemPrompt, user_prompt: userPrompt, validation_errors: validationErrors } }];

const request = $('Validate Input + Route Specialist').item.json;
const agentOutput = $json.output ?? $json.text ?? $json.response ?? JSON.stringify($json);
let structured;
try {
  structured = typeof agentOutput === 'string' ? JSON.parse(agentOutput) : agentOutput;
} catch (error) {
  structured = { score: 0, severity: 'high', assessment: 'requires_changes', summary: 'O AI Agent retornou conteúdo fora do JSON estruturado esperado.', positive_observations: [], findings: [{ severity: 'warning', category: 'quality', message: String(agentOutput), recommendation: 'Ajustar o prompt/schema ou reexecutar a análise.' }], recommendations: ['Validar o formato de saída do agente.'], test_suggestions: [], security_notes: [], complexity_assessment: 'indisponível' };
}
const durationMs = Math.max(0, Date.now() - request.started_at_ms);
const promptTokensEstimate = Math.ceil((request.system_prompt.length + request.user_prompt.length) / 4);
const completionTokensEstimate = Math.ceil(String(agentOutput).length / 4);
const totalTokensEstimate = promptTokensEstimate + completionTokensEstimate;
const estimatedCostUsd = Number((((promptTokensEstimate / 1000000) * 0.15) + ((completionTokensEstimate / 1000000) * 0.60)).toFixed(8));
const response = { data: { flow_type: 'review', status: 'completed', language: request.language, specialist: request.specialist_agent, model_used: request.model, score: structured.score ?? null, severity: structured.severity ?? 'unknown', assessment: structured.assessment ?? 'needs_work', summary: structured.summary ?? '', positive_observations: structured.positive_observations ?? [], findings: structured.findings ?? [], recommendations: structured.recommendations ?? [], test_suggestions: structured.test_suggestions ?? [], security_notes: structured.security_notes ?? [], complexity_assessment: structured.complexity_assessment ?? null }, metrics: { duration_ms: durationMs, prompt_tokens_estimate: promptTokensEstimate, completion_tokens_estimate: completionTokensEstimate, total_tokens_estimate: totalTokensEstimate, estimated_cost_usd: estimatedCostUsd }, observability: { langsmith_required: true, langsmith_project: 'case-n8n', tracing_env: 'LANGCHAIN_TRACING_V2=true' }, meta: { run_id: request.run_id, timestamp: new Date().toISOString() } };
function sql(value) { return String(value).replaceAll(String.fromCharCode(39), String.fromCharCode(39) + String.fromCharCode(39)); }
const inputPayload = JSON.stringify({ language: request.language, context: request.context, code: request.code });
const outputPayload = JSON.stringify(response);
const dbQuery = `INSERT INTO agent_runs (id, flow_type, status, input_payload, output_payload, duration_ms, model_used) VALUES (gen_random_uuid(), 'review', 'completed', '${sql(inputPayload)}'::jsonb, '${sql(outputPayload)}'::jsonb, ${durationMs}, '${sql(response.data.model_used)}');`;
return [{ json: { response, db_query: dbQuery } }];
